namespace ProformaViewer.Models;
public sealed class ProformaEntry { public string Title {get;init;}=""; public string Path {get;init;}=""; public string PageSpec {get;init;}=""; public IReadOnlyList<int> Pages {get;init;}=Array.Empty<int>(); public string FileName=>System.IO.Path.GetFileName(Path); public string PageLabel=>Pages.Count==1?$"Page {Pages[0]}":$"Pages {string.Join(", ",Pages)}"; public string TaskCode{get{var t=Title.Trim();var stop=t.IndexOfAny(new[]{' ','-'});return (stop>0?t[..stop]:t).Trim().ToUpperInvariant();}} }
